    A display title, one span per word; word i takes weights[i] (from the preset). The words wrap like text.
    Props (p): id, title, weights, level. -#}
{%- set v_id = (p.id ?? null) -%}
{%- set v_title = (p.title ?? null) -%}
{%- set v_weights = (p.weights ?? null) -%}
{%- set v_level = (p.level ?? 1) -%}
{%- set c_2 -%}
  {%- for v_word in og_l(og_words(v_title)) %}
    {%- set v_i = loop.index0 -%}
    {%- set c_1 -%}
      {{ og_text(v_word) }}
    {%- endset -%}
    {{ include('compose/Inline.html.twig', {'class': og_s(og_nth(v_weights, v_i)), 'children': c_1}, with_context = false) }}
    {{ og_text(' ') }}
  {%- endfor %}
{%- endset -%}
{{ include('compose/Title.html.twig', {'as': og_i(v_level), 'size': '5xl', 'weight': 'semibold', 'class': og_s(og_cnv(['text-center tracking-tight text-background', og_preset('blocks/presets/defaults.json', ['hero', 'title'])])), 'attrs': og_attrs(['id', v_id]), 'children': c_2}, with_context = false) }}
